def source_module(dim):
    if dim not in [7,12,19,64,71,76,83]:raise ValueError('Unregistered feature dimension')
    if dim not in _MODULES:
        name=f'_ablation_source_dimension_{dim}'
        spec=importlib.util.spec_from_file_location(name,Path(__file__).with_name('frozen_source_numerics.py'))
        module=importlib.util.module_from_spec(spec);sys.modules[name]=module;spec.loader.exec_module(module)
        # Bind only validation/schema width, separately per dimension. No algorithm or old file edit.
        module.CANONICAL_FEATURE_DIMENSIONS=dim;_MODULES[dim]=module
    return _MODULES[dim]

