def fit_head(x,y,gas,params):
    x=np.asarray(x,dtype=np.float64);y=np.asarray(y,dtype=np.float64);gas=int(gas)
    if x.ndim!=2 or y.shape!=(len(x),) or len(y)<2 or x.shape[1]<1 or not np.isfinite(x).all() or not np.isfinite(y).all() or gas not in range(4):raise ValueError('Finite aligned calibration data required')
    mean=x.mean(0);scale=x.std(0,ddof=0);scale[scale<1e-9]=1.
    learner=SVR(kernel='rbf',C=float(params['C']),gamma=float(params['gamma_factor'])/x.shape[1],epsilon=EPSILON,
        tol=.001,shrinking=True,cache_size=200,max_iter=-1)
    learner.fit((x-mean)/scale,(y-LOW[gas])/RANGE[gas])
    if learner.fit_status_!=0:raise ValueError('SVR failed convergence')
    return dict(mean=mean,scale=scale,learner=learner,gas=gas,low=float(LOW[gas]),range=float(RANGE[gas]),
        clip_min=float(y.min()),clip_max=float(y.max()),params=dict(params),epsilon=EPSILON)

def predict_head(head,x,clip=True):
    x=np.asarray(x,dtype=np.float64)
    if x.ndim!=2 or x.shape[1]!=len(head['mean']) or not np.isfinite(x).all():raise ValueError('Predictor input schema/finite mismatch')
    prediction=head['low']+head['range']*head['learner'].predict((x-head['mean'])/head['scale'])
    if not np.isfinite(prediction).all():raise ValueError('Nonfinite SVR prediction')
    return np.clip(prediction,head['clip_min'],head['clip_max']) if clip else prediction

def fit_pair(sensor83, truth, gas, source):
    sensor83, truth, gas, source = (np.asarray(sensor83, dtype=np.float64), np.asarray(truth, dtype=np.float64),
                                   np.asarray(gas, dtype=int), np.asarray(source, dtype=np.float64))
    if sensor83.shape != (len(truth), 83) or source.shape != (len(truth), 4):
        raise ValueError('Training shapes differ')
    direct = (truth - LOW[gas]) / RANGE[gas]
    residual = (truth - source[np.arange(len(truth)), gas]) / RANGE[gas]
    banks = [ModelBank('M0', [], dict(PARAMS)), ModelBank('M1', [], dict(PARAMS))]
    for g in range(4):
        mask = gas == g
        if mask.sum() < 2:
            raise ValueError('At least two calibration windows per gas required')
        mean, scale = sensor83[mask].mean(0), sensor83[mask].std(0)
        scale[scale < 1e-9] = 1.
        z = (sensor83[mask] - mean) / scale
        for bank, target in zip(banks, [direct, residual]):
            learner = SVR(**PARAMS).fit(z, target[mask])
            bank.heads.append(GasHead(mean.copy(), scale.copy(), learner))
    return banks[0], banks[1], dict(M0_normalized=direct, M1_normalized=residual)

