def base(source, gas, alpha):
    # Endpoint branches preserve the exact arithmetic of the frozen controls.
    if alpha == 0:
        return np.full(len(source), c.LOW[gas])
    if alpha == 1:
        return np.asarray(source, dtype=float)
    return c.LOW[gas] + alpha * (np.asarray(source, dtype=float) - c.LOW[gas])

def fit_head(x, truth, source, gas, alpha):
    x, truth, source = np.asarray(x, float), np.asarray(truth, float), np.asarray(source, float)
    if x.shape != (len(truth), 83) or source.shape != truth.shape or len(truth) < 2:
        raise ValueError('At least two finite83D training windows and matching source/truth required')
    if not 0 <= alpha <= 1 or not np.isfinite(x).all() or not np.isfinite(truth).all() or not np.isfinite(source).all():
        raise ValueError('Invalid alpha or nonfinite training input')
    mean, scale = x.mean(0), x.std(0)
    scale[scale < 1e-9] = 1.
    residual = (truth - base(source, gas, alpha)) / c.RANGE[gas]
    learner = SVR(**c.PARAMS).fit((x - mean) / scale, residual)
    if learner.fit_status_:
        raise ValueError('SVR failed to converge')
    return AlphaHead(mean, scale, learner, int(gas), float(alpha))

def folds(groups):
    groups = np.asarray(groups)
    if len(np.unique(groups)) < 3:
        raise ValueError('Leave-one-exposure-out needs at least three groups')
    for name in sorted(set(groups)):
        train, valid = np.flatnonzero(groups != name), np.flatnonzero(groups == name)
        if len(train) < 2:
            raise ValueError('Insufficient training rows after exposure holdout')
        yield train, valid

def choose_alphas(oof):
    def best(part):
        scores = part.groupby('alpha').nse.mean()
        return float(min(scores[scores <= scores.min() + 1e-12].index))
    return best(oof), {int(gas): best(part) for gas, part in oof.groupby('gas')}

def assign_folds(gas, groups, seed=42):
    gas, groups = np.asarray(gas, int), np.asarray(groups, str)
    if gas.shape != groups.shape or set(gas) != {0,1,2,3}:
        raise ValueError('four gas classes with matching exposure IDs required')
    for name in set(groups):
        if len(set(gas[groups==name])) != 1:
            raise ValueError('One exposure ID cannot belong to different gases')
    result = np.full(len(gas), -1, int)
    rng = np.random.default_rng(seed)
    for g in range(4):
        names = sorted(set(groups[gas==g]))
        if len(names) < 4:
            raise ValueError(f'At least four independent exposures required for gas{g}')
        for j,name in enumerate(rng.permutation(names)):
            result[groups==name] = j % 4
    for k in range(4):
        if any(np.sum((result==k)&(gas==g))<1 or np.sum((result!=k)&(gas==g))<2 for g in range(4)):
            raise ValueError('Invalid four-fold calibration training/validation counts')
        if set(groups[result==k]) & set(groups[result!=k]):
            raise ValueError('Exposure group leakage')
    return result

def fit_head(x, truth, source, gas, rho):
    x, truth, source = np.asarray(x,float), np.asarray(truth,float), np.asarray(source,float)
    if x.shape != (len(truth),83) or source.shape != truth.shape or len(truth)<2:
        raise ValueError('Matching83D calibration arrays with at least two windows required')
    if not 0<=rho<=1 or not all(np.isfinite(z).all() for z in [x,truth,source]):
        raise ValueError('Nonfinite input or invalid rho')
    mean,scale=x.mean(0),x.std(0); scale[scale<1e-9]=1.
    # Fixed translation of the physical residual, restored in the intercept.
    # rho0/rho1 retain exactly the old M0/M1 numerical centering, respectively.
    offset=(1.-rho)*c.LOW[gas]
    residual=(truth-rho*source-offset)/c.RANGE[gas]
    learner=SVR(**c.PARAMS).fit((x-mean)/scale,residual)
    if learner.fit_status_:
        raise ValueError('SVR convergence failed')
    return PriorHead(mean,scale,learner,int(gas),float(rho),float(offset))

def choose_rho(scores):
    if scores.rho.duplicated().any() or not np.isfinite(scores.NRMSE.to_numpy()).all():
        raise ValueError('One finite pooled NRMSE per candidate required')
    return float(scores.sort_values(['NRMSE','rho'],kind='stable').iloc[0].rho)

